t=np.arange(0,31); funding=100-2.2*t; market=100-1.0*t-0.05*t**2; ax.plot(t,funding,color=BAD,lw=2,label='Funding buffer (%)'); ax.plot(t,market,color=WARM,lw=2,label='Market liquidity index'); ax.axhline(40,color=INK,ls='--',lw=.8,label='Action threshold'); ax.set_xlabel('Stress day'); ax.set_ylabel('Index / percent'); ax.set_title('Illustrative liquidity depletion',loc='left'); ax.legend(fontsize=7); ax.grid(alpha=.25); ax.set_ylim(0,105)
